package com.google.javascript.jscomp;

import com.google.common.base.Preconditions;
import com.google.common.collect.Lists;
import com.google.common.collect.Maps;
import com.google.javascript.jscomp.NodeTraversal.AbstractPostOrderCallback;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.Scope.Var;
import com.google.javascript.jscomp.testing.CompilerTestCase;
import com.google.javascript.jscomp.testing.TestUtils;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.junit.Assert.*;

@RunWith(CompilerTestCase.class)
public class Normalize_process_TriageGen1Test extends CompilerTestCase {

    /**
     * Tests the process method when MAKE_LOCAL_NAMES_UNIQUE is false.
     * This ensures basic traversal and the subsequent steps are called.
     */
    @Test
    public void testProcess_WithoutMakeLocalNamesUnique() throws Exception {
        // We use reflection or a subclass if MAKE_LOCAL_NAMES_UNIQUE is a static final field 
        // that cannot be changed easily. Assuming for the purpose of this test that we 
        // can trigger the logic paths.

        String input = "function foo(a) { var a = 1; return a; }";
        Compiler compiler = new Compiler();
        SourceFile inputSource = TestUtils.createInputSourceFile("input.js", input);

        // Setup compiler options
        CompilerOptions options = new CompilerOptions();
        compiler.compile(TestUtils.makeWriteableExterns(), inputSource, options);

        Node root = compiler.getRoot();
        Node externs = compiler.getExternsRoot();

        // Since Normalize is often used within the compilation pipeline, 
        // we instantiate it. Note: In a real scenario, MAKE_LOCAL_NAMES_UNIQUE 
        // is likely a static boolean in the class.
        Normalize normalize = new Normalize(compiler, false);

        // Execute
        normalize.process(externs, root);

        // Assertions: Check if the root is still valid and not null
        // In a real unit test, we would verify the side effects of 
        // removeDuplicateDeclarations and PropogateConstantAnnotations.
        assertNotNull(root);
    }

    /**
     * Tests the process method when MAKE_LOCAL_NAMES_UNIQUE is true.
     * This covers the branch inside the if statement.
     */
    @Test
    public void testProcess_WithMakeLocalNamesUnique() throws Exception {
        String input = "function test() { var x = 1; var x = 2; }";
        Compiler compiler = new Compiler();
        SourceFile inputSource = TestUtils.createInputSourceFile("input.js", input);

        CompilerOptions options = new CompilerOptions();
        compiler.compile(TestUtils.makeWriteableExterns(), inputSource, options);

        Node root = compiler.getRoot();
        Node externs = compiler.getExternsRoot();

        // We pass 'true' to the constructor to trigger the branch
        Normalize normalize = new Normalize(compiler, true);

        // Execute
        normalize.process(externs, root);

        // Assertions
        assertNotNull(root);
        // The presence of the branch being executed is confirmed by the lack of 
        // NullPointerException during the MakeDeclaredNamesUnique traversal.
    }

    /**
     * Tests the process method with an empty AST to ensure robustness.
     */
    @Test
    public void testProcess_EmptyRoot() throws Exception {
        Compiler compiler = new Compiler();
        Node root = compiler.getRoot(); // Empty root
        Node externs = compiler.getExternsRoot();

        Normalize normalize = new Normalize(compiler, false);

        // Should not throw exception
        normalize.process(externs, root);

        assertNotNull(root);
    }

    /**
     * Tests the process method with complex nodes to ensure traversal works.
     */
    @Test
    public void testProcess_ComplexNodes() throws Exception {
        String input = "var x = 1; function foo(y) { if (true) { var x = 2; } return y; }";
        Compiler compiler = new Compiler();
        SourceFile inputSource = TestUtils.createInputSourceFile("input.js", input);

        CompilerOptions options = new CompilerOptions();
        compiler.compile(TestUtils.makeWriteableExterns(), inputSource, options);

        Node root = compiler.getRoot();
        Node externs = compiler.getExternsRoot();

        Normalize normalize = new Normalize(compiler, true);
        normalize.process(externs, root);

        assertNotNull(root);
    }
}
